// The token request's test script (Postman sandbox): assert, then chain the token and the kid into the environment
pm.test('200', () => pm.response.to.have.status(200));
const t = pm.response.json();
pm.test('bearer token with a lifetime', () => { pm.expect(t.token_type).to.eql('Bearer'); pm.expect(t.expires_in).to.be.above(0); });
pm.test('no refresh token for client credentials', () => pm.expect(t.refresh_token).to.be.undefined);
pm.environment.set('access_token', t.access_token);
const hdr = JSON.parse(atob(t.access_token.split('.')[0].replace(/-/g, '+').replace(/_/g, '/')));
pm.test('JWT header has alg and kid', () => { pm.expect(hdr.alg).to.eql('RS256'); pm.expect(hdr.kid).to.be.a('string'); });
pm.environment.set('kid', hdr.kid);

# token.bru: one request per file, auth from variables; the secret is declared by name only in the environment file
meta {
  name: token (client credentials)
  type: http
  seq: 1
}

post {
  url: {{issuer}}/protocol/openid-connect/token
  body: formUrlEncoded
  auth: basic
}

auth:basic {
  username: {{client_id}}
  password: {{client_secret}}
}

body:form-urlencoded {
  grant_type: client_credentials
  scope: openid
}

tests {
  test("200", function() { expect(res.getStatus()).to.equal(200); });
  test("bearer with lifetime", function() { expect(res.getBody().token_type).to.equal("Bearer"); expect(res.getBody().expires_in).to.be.above(0); });
  bru.setVar("access_token", res.getBody().access_token);
}

